#include "tarot_runtime.h"
void tarot_runtime_init(tarot_runtime_t*r,int64_t n){if(!r)return;*r=(tarot_runtime_t){.last_input_us=n,.next_battery_refresh_us=n+TAROT_BATTERY_REFRESH_US,.idle_state=TAROT_IDLE_ACTIVE};}tarot_idle_state_t tarot_runtime_update_idle(tarot_runtime_t*r,int64_t n){if(!r)return TAROT_IDLE_ACTIVE;int64_t i=n-r->last_input_us;r->idle_state=i>=TAROT_OFF_AFTER_US?TAROT_IDLE_OFF:i>=TAROT_DIM_AFTER_US?TAROT_IDLE_DIMMED:TAROT_IDLE_ACTIVE;return r->idle_state;}bool tarot_runtime_note_input(tarot_runtime_t*r,int64_t n,bool p,bool*w){if(w)*w=false;if(!r)return false;bool off=r->idle_state==TAROT_IDLE_OFF;r->last_input_us=n;r->idle_state=TAROT_IDLE_ACTIVE;if(off){r->suppress_until_next_press=true;if(w)*w=true;return false;}if(r->suppress_until_next_press){if(p)r->suppress_until_next_press=false;return false;}return !p;}bool tarot_runtime_battery_refresh_due(tarot_runtime_t*r,int64_t n){if(!r||n<r->next_battery_refresh_us)return false;r->next_battery_refresh_us=n+TAROT_BATTERY_REFRESH_US;return true;}
